// PATCH: smoke-plan covers local-only approved live-smoke planning guidance and safety metadata.
// PATCH: smoke-run-approval-gated covers approval gates and fake-server smoke execution.
func TestSmokePlanNoArgJSONReturnsScopesAndSafety(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "smoke", "plan", "--json")
	if err != nil {
		t.Fatalf("smoke plan --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("smoke plan wrote stderr: %q", stderr)
	}

	var got smokePlanResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("smoke plan --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "smoke plan" {
		t.Fatalf("command = %q, want smoke plan", got.Command)
	}
	wantScopes := []string{"setup", "customers", "payments", "funding", "mcp", "approval", "all"}
	if strings.Join(got.AvailableScopes, ",") != strings.Join(wantScopes, ",") {
		t.Fatalf("available scopes = %#v, want %#v", got.AvailableScopes, wantScopes)
	}
	if !got.Safety.GuidanceOnly || !got.Safety.LocalOnly || !got.Safety.RequiresExplicitApproval {
		t.Fatalf("smoke plan should be local guidance requiring approval: %#v", got.Safety)
	}
	if !got.Safety.RequiresSandboxOrApprovedCredential || !got.Safety.RequiresCredentialThroughSecureFlow {
		t.Fatalf("smoke plan should require approved credentials through a secure flow: %#v", got.Safety)
	}
	if !got.Safety.ReadOnlyIntendedCommandsOnly || !got.Safety.NoWrites || !got.Safety.NoTokenLiterals || !got.Safety.NoLiveExecutionInCommand {
		t.Fatalf("smoke plan should be read-only guidance without tokens or live execution: %#v", got.Safety)
	}
	if got.Safety.MakesAPICalls || got.Safety.CallsDocsEndpoint || got.Safety.ExecutesMCP || got.Safety.PostsWebhook || got.Safety.WritesSandbox || got.Safety.WritesProduction {
		t.Fatalf("smoke plan should not touch APIs, docs, MCP, webhooks, sandbox, or production: %#v", got.Safety)
	}
}

func TestSmokePlanScopesIncludeExpectedCommands(t *testing.T) {
	tests := map[string][]string{
		"setup": {
			"straddle-pp-cli setup check --json",
		},
		"customers": {
			"straddle-pp-cli setup check --json",
			"straddle-pp-cli customers list --dry-run --agent",
		},
		"payments": {
			"straddle-pp-cli payments --dry-run --agent",
		},
		"funding": {
			"straddle-pp-cli funding-events list --dry-run --agent",
		},
		"mcp": {
			"straddle-pp-cli setup check --json",
		},
		"approval": {
			"straddle-pp-cli smoke plan setup --json",
			"straddle-pp-cli smoke plan customers --json",
			"straddle-pp-cli docs search sandbox --source commands --json",
		},
	}

	for scope, wantCommands := range tests {
		t.Run(scope, func(t *testing.T) {
			stdout, stderr, err := runCLIForDocsTest(t, "smoke", "plan", scope, "--json")
			if err != nil {
				t.Fatalf("smoke plan %s --json returned error: %v", scope, err)
			}
			if stderr != "" {
				t.Fatalf("smoke plan %s wrote stderr: %q", scope, stderr)
			}

			var got smokePlanResponse
			if err := json.Unmarshal([]byte(stdout), &got); err != nil {
				t.Fatalf("smoke plan %s --json emitted invalid JSON: %v\n%s", scope, err, stdout)
			}
			if got.Scope != scope || got.ScopePlan == nil {
				t.Fatalf("expected %s scope plan, got %#v", scope, got)
			}
			for _, want := range wantCommands {
				if !containsString(got.ScopePlan.CommandSuggestions, want) {
					t.Fatalf("%s scope commands = %#v, want %q", scope, got.ScopePlan.CommandSuggestions, want)
				}
			}
			if len(got.ScopePlan.DocsQueries) == 0 {
				t.Fatalf("%s scope should include docs lookup topics", scope)
			}
			if strings.Contains(stdout, "STRADDLE_TOKEN=") || strings.Contains(stdout, "Bearer ") {
				t.Fatalf("smoke plan should not emit token literals or bearer examples:\n%s", stdout)
			}
		})
	}
}

func TestSmokePlanCommandSuggestionsResolveToRealCommands(t *testing.T) {
	root := newRootCmd(&rootFlags{})
	for _, plan := range smokeScopePlans() {
		t.Run(plan.Name, func(t *testing.T) {
			for _, suggestion := range plan.CommandSuggestions {
				path := commandPathFromSuggestion(t, suggestion)
				cmd, _, err := root.Find(path)
				if err != nil {
					t.Fatalf("suggestion %q did not resolve: %v", suggestion, err)
				}
				if cmd == nil {
					t.Fatalf("suggestion %q resolved to nil command", suggestion)
				}
				if cmd.Run == nil && cmd.RunE == nil {
					t.Fatalf("suggestion %q resolved to %q without executable behavior", suggestion, cmd.CommandPath())
				}
			}
		})
	}
}

